<script setup lang="ts">
import {computed} from 'vue';
export type LiveTranscriptEvent={eventId:string;segmentId:string;revision:number;status:'temporary'|'stable';text:string;startMs:number;endMs:number};
const props=defineProps<{events:LiveTranscriptEvent[];afterEventId?:string|null;delayed?:boolean}>();
const emit=defineEmits<{recover:[afterEventId:string|null]}>();
const visible=computed(()=>{const bySegment=new Map<string,LiveTranscriptEvent>();for(const event of props.events){const current=bySegment.get(event.segmentId);if(!current||event.revision>current.revision)bySegment.set(event.segmentId,event);}return [...bySegment.values()].sort((a,b)=>a.startMs-b.startMs||a.segmentId.localeCompare(b.segmentId));});
function clock(ms:number){const value=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`;}
</script>
<template><section class="live-transcript" aria-label="实时转写"><header><strong>实时转写</strong><span v-if="delayed" role="status">识别积压，正在补处理</span></header><p v-if="!visible.length" class="muted">等待会议内容</p><ol v-else><li v-for="event in visible" :key="event.segmentId" :data-event-id="event.eventId"><time>{{clock(event.startMs)}}</time><span class="live-speaker">匿名说话人</span><span class="live-text">{{event.text}}</span><small>{{event.status==='stable'?'稳定':'临时'}}</small></li></ol><button v-if="afterEventId" type="button" class="btn sm" @click="emit('recover',afterEventId??null)">恢复断线字幕</button></section></template>
<style scoped>.live-transcript{padding:16px;border:1px solid var(--border);border-radius:8px;background:#fff}.live-transcript header{display:flex;justify-content:space-between;gap:12px}.live-transcript header span,.live-transcript small,.muted{color:var(--muted);font-size:12px}.live-transcript ol{list-style:none;padding:0;margin:12px 0}.live-transcript li{display:grid;grid-template-columns:54px 88px 1fr auto;gap:8px;padding:9px 0;border-bottom:1px solid var(--border)}.live-speaker{color:var(--blue);font-size:12px}.live-text{white-space:pre-wrap;overflow-wrap:anywhere}.live-transcript time{font-variant-numeric:tabular-nums;color:var(--muted);font-size:12px}</style>
